  const head=(title,subtitle,action='')=>`<div class="page-head"><div><span class="eyebrow">PARTNERPORTAL / ${P.role==='internal'?'INTERNT TEAM':e(partners[P.partner])}</span><h1>${title}</h1><p class="muted">${subtitle}</p></div>${action}</div>`;
